-- RCMAA — seeded content dump
--
-- Committee members, events, gallery, notices, FAQs and pages, as they stand on
-- the development machine. Contains NO registrations and NO user accounts: the
-- admin login is created by DatabaseSeeder from RCMAA_ADMIN_* in .env, and
-- registrations are real people's data.
--
-- This is a reference and a safety net. The canonical way to build the database
-- is still:
--     php artisan migrate --seed
--
-- To load this dump into a fresh SQLite file instead:
--     sqlite3 database/database.sqlite < database/dumps/rcmaa-seed.sql
--     php artisan db:seed          # adds the admin user from .env
--
PRAGMA foreign_keys=OFF;
BEGIN TRANSACTION;
CREATE TABLE IF NOT EXISTS "migrations" ("id" integer primary key autoincrement not null, "migration" varchar not null, "batch" integer not null);
CREATE TABLE IF NOT EXISTS "users" ("id" integer primary key autoincrement not null, "name" varchar not null, "email" varchar not null, "email_verified_at" datetime, "password" varchar not null, "remember_token" varchar, "created_at" datetime, "updated_at" datetime, "is_admin" tinyint(1) not null default '0');
CREATE TABLE IF NOT EXISTS "password_reset_tokens" ("email" varchar not null, "token" varchar not null, "created_at" datetime, primary key ("email"));
CREATE TABLE IF NOT EXISTS "sessions" ("id" varchar not null, "user_id" integer, "ip_address" varchar, "user_agent" text, "payload" text not null, "last_activity" integer not null, primary key ("id"));
CREATE TABLE IF NOT EXISTS "cache" ("key" varchar not null, "value" text not null, "expiration" integer not null, primary key ("key"));
CREATE TABLE IF NOT EXISTS "cache_locks" ("key" varchar not null, "owner" varchar not null, "expiration" integer not null, primary key ("key"));
CREATE TABLE IF NOT EXISTS "jobs" ("id" integer primary key autoincrement not null, "queue" varchar not null, "payload" text not null, "attempts" integer not null, "reserved_at" integer, "available_at" integer not null, "created_at" integer not null);
CREATE TABLE IF NOT EXISTS "job_batches" ("id" varchar not null, "name" varchar not null, "total_jobs" integer not null, "pending_jobs" integer not null, "failed_jobs" integer not null, "failed_job_ids" text not null, "options" text, "cancelled_at" integer, "created_at" integer not null, "finished_at" integer, primary key ("id"));
CREATE TABLE IF NOT EXISTS "failed_jobs" ("id" integer primary key autoincrement not null, "uuid" varchar not null, "connection" varchar not null, "queue" varchar not null, "payload" text not null, "exception" text not null, "failed_at" datetime not null default CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS "registrations" ("id" integer primary key autoincrement not null, "reference" varchar not null, "full_name_en" varchar not null, "full_name_bn" varchar, "blood_group" varchar, "mobile" varchar not null, "whatsapp" varchar, "email" varchar not null, "present_address" text not null, "permanent_address" text, "session" varchar not null, "degree" varchar not null, "class_roll" varchar, "registration_no" varchar, "passing_year" integer not null, "employment_status" varchar not null, "profession" varchar, "designation" varchar, "organization" varchar, "tshirt_size" varchar not null, "cultural_program" tinyint(1) not null default '0', "guest_count" varchar not null default '0', "guests" text, "memories" text, "photo_path" varchar, "payment_method" varchar not null, "transaction_id" varchar not null, "sender_number" varchar not null, "amount_paid" integer not null, "amount_due" integer not null default '0', "payment_status" varchar not null default 'pending', "verified_at" datetime, "verified_by" integer, "admin_note" text, "ip_address" varchar, "created_at" datetime, "updated_at" datetime, "category" varchar not null default 'alumni', "category_fee" integer not null default '0', "guest_fee" integer not null default '0', "listed_in_directory" tinyint(1) not null default '1', "payment_receipt_path" varchar, foreign key("verified_by") references "users"("id") on delete set null);
CREATE TABLE IF NOT EXISTS "committee_members" ("id" integer primary key autoincrement not null, "committee" varchar not null, "name" varchar not null, "name_bn" varchar, "designation" varchar not null, "designation_bn" varchar, "batch" varchar, "profession" varchar, "phone" varchar, "email" varchar, "photo_path" varchar, "bio" text, "sort_order" integer not null default '0', "is_featured" tinyint(1) not null default '0', "is_published" tinyint(1) not null default '1', "created_at" datetime, "updated_at" datetime);
CREATE TABLE IF NOT EXISTS "teachers" ("id" integer primary key autoincrement not null, "name" varchar not null, "designation" varchar not null, "qualification" varchar, "specialisation" varchar, "email" varchar, "phone" varchar, "photo_path" varchar, "bio" text, "is_head" tinyint(1) not null default '0', "sort_order" integer not null default '0', "is_published" tinyint(1) not null default '1', "created_at" datetime, "updated_at" datetime);
CREATE TABLE IF NOT EXISTS "events" ("id" integer primary key autoincrement not null, "title" varchar not null, "slug" varchar not null, "excerpt" text, "body" text, "starts_on" date not null, "ends_on" date, "start_time" varchar, "venue" varchar, "cover_path" varchar, "registration_open" tinyint(1) not null default '0', "is_featured" tinyint(1) not null default '0', "is_published" tinyint(1) not null default '1', "created_at" datetime, "updated_at" datetime);
CREATE TABLE IF NOT EXISTS "notices" ("id" integer primary key autoincrement not null, "title" varchar not null, "slug" varchar not null, "excerpt" text, "body" text, "attachment_path" varchar, "published_on" date not null, "is_pinned" tinyint(1) not null default '0', "is_published" tinyint(1) not null default '1', "created_at" datetime, "updated_at" datetime);
CREATE TABLE IF NOT EXISTS "gallery_items" ("id" integer primary key autoincrement not null, "title" varchar not null, "caption" text, "category" varchar not null default 'campus', "image_path" varchar not null, "sort_order" integer not null default '0', "is_featured" tinyint(1) not null default '0', "is_published" tinyint(1) not null default '1', "created_at" datetime, "updated_at" datetime);
CREATE TABLE IF NOT EXISTS "faqs" ("id" integer primary key autoincrement not null, "question" varchar not null, "answer" text not null, "category" varchar not null default 'general', "sort_order" integer not null default '0', "is_published" tinyint(1) not null default '1', "created_at" datetime, "updated_at" datetime);
CREATE TABLE IF NOT EXISTS "sponsors" ("id" integer primary key autoincrement not null, "name" varchar not null, "tier" varchar not null default 'partner', "website" varchar, "logo_path" varchar, "sort_order" integer not null default '0', "is_published" tinyint(1) not null default '1', "created_at" datetime, "updated_at" datetime);
CREATE TABLE IF NOT EXISTS "contact_messages" ("id" integer primary key autoincrement not null, "name" varchar not null, "email" varchar not null, "phone" varchar, "subject" varchar not null, "message" text not null, "is_read" tinyint(1) not null default '0', "ip_address" varchar, "created_at" datetime, "updated_at" datetime);
CREATE UNIQUE INDEX "users_email_unique" on "users" ("email");
CREATE INDEX "sessions_user_id_index" on "sessions" ("user_id");
CREATE INDEX "sessions_last_activity_index" on "sessions" ("last_activity");
CREATE INDEX "cache_expiration_index" on "cache" ("expiration");
CREATE INDEX "cache_locks_expiration_index" on "cache_locks" ("expiration");
CREATE INDEX "jobs_queue_index" on "jobs" ("queue");
CREATE INDEX "failed_jobs_connection_queue_failed_at_index" on "failed_jobs" ("connection", "queue", "failed_at");
CREATE UNIQUE INDEX "failed_jobs_uuid_unique" on "failed_jobs" ("uuid");
CREATE INDEX "registrations_payment_status_index" on "registrations" ("payment_status");
CREATE INDEX "registrations_passing_year_index" on "registrations" ("passing_year");
CREATE INDEX "registrations_email_index" on "registrations" ("email");
CREATE UNIQUE INDEX "registrations_payment_method_transaction_id_unique" on "registrations" ("payment_method", "transaction_id");
CREATE UNIQUE INDEX "registrations_reference_unique" on "registrations" ("reference");
CREATE INDEX "committee_members_committee_index" on "committee_members" ("committee");
CREATE INDEX "events_starts_on_index" on "events" ("starts_on");
CREATE UNIQUE INDEX "events_slug_unique" on "events" ("slug");
CREATE INDEX "notices_published_on_index" on "notices" ("published_on");
CREATE UNIQUE INDEX "notices_slug_unique" on "notices" ("slug");
CREATE INDEX "gallery_items_category_index" on "gallery_items" ("category");
CREATE INDEX "faqs_category_index" on "faqs" ("category");
CREATE INDEX "registrations_category_index" on "registrations" ("category");
CREATE INDEX "registrations_listed_in_directory_index" on "registrations" ("listed_in_directory");
COMMIT;
