INSERT INTO events VALUES(1,'General Meeting','general-meeting','A general meeting of the Rajshahi College Mathematics Alumni Association to review reunion preparations and association business.',NULL,'2026-08-01 00:00:00',NULL,NULL,'Department of Mathematics, Rajshahi College','events/general-meeting.png',0,0,1,'2026-08-03 16:35:08','2026-08-03 16:35:08');
INSERT INTO events VALUES(2,'Math Nexus — Grand Reunion 2026','math-nexus-grand-reunion-2026','The grand reunion of the Department of Mathematics: reconnect with old friends, network with fellow graduates and celebrate our shared legacy.',unistr('Math Nexus is the association''s largest undertaking to date.\u000a\u000aIt is not merely a reunion, but an attempt to build a strong bridge of relationships, memories, experience and cooperation from one generation of the Department of Mathematics to the next.\u000a\u000aWritten approval for the event was received from the Principal of Rajshahi College on 25 January 2026.'),'2026-12-19 00:00:00',NULL,'9:00 AM — 9:00 PM','Rajshahi College Campus, Rajshahi','events/math-nexus.png',1,1,1,'2026-08-03 16:35:08','2026-08-03 16:35:08');
INSERT INTO notices VALUES(1,'Registration open for the Grand Reunion 2026','registration-open-for-the-grand-reunion-2026','Online registration for Math Nexus — the Grand Reunion of the Department of Mathematics — is now open.',unistr('Online registration for **Math Nexus, the Grand Reunion 2026**, is now open to all graduates of the Department of Mathematics, Rajshahi College.\u000a\u000aComplete the registration form on this website, pay the registration fee to one of the listed mobile financial service numbers, and enter your transaction ID on the final step. Your registration will be verified by the committee within one to two working days, after which you can confirm it using your reference number.\u000a\u000aPlease note that prior registration is mandatory in order to perform in the cultural programme on the event day.'),NULL,'2026-07-01 00:00:00',1,1,'2026-08-03 16:35:08','2026-08-03 16:35:08');
INSERT INTO notices VALUES(2,'General Meeting — 01 August','general-meeting-01-august','All members are requested to attend the general meeting of the association on 01 August.',unistr('All members of the Rajshahi College Mathematics Alumni Association are requested to attend the general meeting on **01 August** at the Department of Mathematics, Rajshahi College.\u000a\u000aThe agenda covers reunion preparations, the sub-committee reports and the association''s ongoing business.'),NULL,'2026-07-20 00:00:00',0,1,'2026-08-03 16:35:08','2026-08-03 16:35:08');
